<?php
if($page==='hr_document'){
    $doc=row('SELECT * FROM employee_documents WHERE id=?',[max(0,(int)($_GET['id']??0))]);if(!$doc){emptyState('Attestation introuvable.','Revenez aux employés.');return;}
    $s=json_decode($doc['snapshot'],true,512,JSON_THROW_ON_ERROR);require_once __DIR__.'/payroll_pdf.php';heading('DOCUMENT RH',$doc['number'],'Informations conservées à l’émission.');
    ?><div class="document-actions"><a class="btn secondary" href="<?=e(url('employee_form',['id'=>$doc['employee_id']]))?>">← Employé</a><a class="btn primary" href="<?=e(url('hr_document',['id'=>$doc['id'],'download'=>'pdf']))?>">↓ Télécharger PDF</a></div><article class="document-sheet"><h2><?=e($doc['kind']==='work'?'Attestation de travail':'Attestation de salaire de base')?></h2><p><?=nl2br(e(attestationText($s)))?></p><p>Fait à <?=e($s['place'])?>, le <?=e($s['issued_date'])?></p><p><?=e($s['signatory'])?> · Signature et cachet</p></article><?php return;
}
$id=max(0,(int)($_GET['id']??0));$record=$id?row('SELECT * FROM payroll_records WHERE id=?',[$id]):false;if($id&&!$record){emptyState('Fiche introuvable.','Revenez aux employés.');return;}
$employeeId=$record?(int)$record['employee_id']:max(0,(int)($_GET['employee_id']??0));$emp=row('SELECT * FROM employees WHERE id=?',[$employeeId]);if(!$emp){emptyState('Employé introuvable.','Ouvrez une fiche employé.');return;}
$v=$record?:['period'=>date('Y-m'),'base_salary'=>$emp['base_salary']??'0.00','bonus'=>$emp['default_bonus']??'0.00','social_deductions'=>'0.00','income_tax'=>'0.00','other_deductions'=>'0.00','note'=>'','revision'=>1];if(($_POST['action']??'')==='payroll_save')$v=$_POST+$v;
heading('PAIE DE L’ÉQUIPE',$record&&$record['state']==='Émis'?$record['number']:'Préparer une fiche de paie.',$emp['full_name'].' · saisie et validation par l’administrateur');
?><div class="document-actions"><a class="btn secondary" href="<?=e(url('employee_form',['id'=>$employeeId]))?>">← Employé</a></div><?php if($record&&$record['state']==='Émis'):$s=json_decode($record['snapshot'],true,512,JSON_THROW_ON_ERROR);?><section class="panel padded"><h2><?=e($s['employee']['full_name'])?> · <?=e($s['payroll']['period'])?></h2><p>Émise le <?=e(localDate($record['issued_at']))?>. Coordonnées et montants conservés.</p><div class="finance-summary"><?php foreach(['gross'=>'Brut','deductions'=>'Retenues','net'=>'Net à payer'] as $k=>$label):?><div><span><?=e($label)?></span><strong><?=e(money(decimalString($s['totals'][$k],2)))?></strong></div><?php endforeach?></div><a class="btn primary" href="<?=e(url('payroll_form',['id'=>$id,'download'=>'pdf']))?>">↓ Fiche de paie PDF</a></section><?php return;endif?>
<form method="post" class="panel editor-form" id="payroll-form"><?=csrf()?><input type="hidden" name="action" value="payroll_save"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="employee_id" value="<?=$employeeId?>"><input type="hidden" name="revision" value="<?=e($v['revision'])?>"><input type="hidden" name="request_key" value="<?=e($_POST['request_key']??bin2hex(random_bytes(32)))?>"><div class="form-grid"><?php inputField('Mois','period',$v['period'],'month',true,$id?'readonly':'');foreach(PAYROLL_FIELDS as $k=>$label)inputField($label.' · DH',$k,$v[$k],'number',true,'min="0" max="999999999.99" step="0.01" data-pay-amount');?><label class="full-width">Note / détail des primes et retenues<textarea name="note" rows="3" maxlength="1500"><?=e($v['note'])?></textarea></label></div><div class="finance-summary" aria-live="polite"><div><span>Brut</span><strong data-pay-total="gross">—</strong></div><div><span>Retenues</span><strong data-pay-total="deductions">—</strong></div><div><span>Net à payer</span><strong data-pay-total="net">—</strong></div></div><p data-pay-error role="alert"></p><p class="small muted">Cotisations, impôt et autres retenues sont saisis manuellement. Les absences ne génèrent aucune déduction automatique. Les montants doivent être validés avant émission.</p><div class="form-footer"><button class="btn primary">Enregistrer le brouillon</button></div></form>
<?php if($record):?><section class="panel padded commerce-block"><h2>Émettre la fiche enregistrée</h2><p class="small muted">Après émission, les informations et montants sont conservés sans modification. Enregistrez d’abord toute correction du formulaire.</p><form method="post" data-confirm="Émettre définitivement cette fiche de paie après vérification ?"><?=csrf()?><input type="hidden" name="action" value="payroll_issue"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="revision" value="<?=(int)$record['revision']?>"><label><input type="checkbox" name="issue_confirmed" value="1" required> J’ai validé le brut, les primes et toutes les retenues.</label><button class="btn primary" data-issue-payroll <?=$error!==''?'disabled':''?>>Émettre la fiche de paie</button></form></section><?php endif?>
